<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,Booking};use App\Services\{VenueSettings,BookingEngine};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use Tests\TestCase;
class PlatformTest extends TestCase {
 use RefreshDatabase;
 private function owner(?User $u=null):Owner{$u??=User::factory()->create();return Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));}
 private function venue(?User $owner=null,array $override=[]):Venue{$owner??=User::factory()->create();$account=$this->owner($owner);return Venue::create(['owner_id'=>$owner->id,'owner_account_id'=>$account->id,'slug'=>'jardin-'.Str::lower(Str::random(8)),'name'=>'Jardín de prueba','published'=>true,'settings'=>array_replace_recursive(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>120,'included_hours'=>8,'weekday_price'=>650000,'weekend_price'=>850000,'holiday_price'=>1050000,'extra_hour_price'=>85000,'deposit_value'=>30,'address'=>'Colima, México','lat'=>19.24,'lng'=>-103.72],$override)]);}
 private function input():array{return ['policy_accepted'=>true,'date'=>now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>50];}
 public function test_registration_collects_minimal_information_and_hashes_password():void{$this->postJson('/api/register',['name'=>'Cliente Uno','email'=>'cliente@example.com','password'=>'ClaveSegura123','password_confirmation'=>'ClaveSegura123'])->assertCreated()->assertJsonPath('user.name','Cliente Uno');$this->assertAuthenticated();$this->assertNotEquals('ClaveSegura123',User::first()->password);}
 public function test_guest_cannot_create_a_booking():void{$v=$this->venue();$this->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertUnauthorized();}
 public function test_guest_cannot_read_owner_data():void{$this->getJson('/api/owner/venues')->assertNotFound();}
 public function test_owner_scope_and_encrypted_secret():void{$u=User::factory()->create();$v=$this->venue($u);$v->ai_key='test-secret-not-real';$v->save();$this->assertNotEquals('test-secret-not-real',$v->getRawOriginal('ai_key'));$this->getJson('/api/venues/'.$v->slug)->assertOk()->assertJsonMissingPath('ai_key')->assertJsonMissingPath('settings.ai');$this->actingAs(User::factory()->create())->getJson('/api/owner/venues/'.$v->slug.'/bookings')->assertForbidden();}
 public function test_another_owner_cannot_update_a_venue():void{$v=$this->venue();$this->actingAs(User::factory()->create())->putJson('/api/owner/venues/'.$v->slug,[])->assertForbidden();}
 public function test_owner_can_create_dynamic_venue():void{$u=User::factory()->create();$s=array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>120,'included_hours'=>8,'weekday_price'=>650000,'weekend_price'=>850000,'holiday_price'=>1050000,'extra_hour_price'=>85000,'deposit_value'=>30]);$s['address']='Colima, México';$s['lat']=19.24;$s['lng']=-103.72;$this->actingAs($this->owner($u))->postJson('/api/owner/venues',['name'=>'Local real','slug'=>'local-real','published'=>true,'settings'=>$s])->assertCreated();$this->getJson('/api/venues/local-real')->assertOk()->assertJsonPath('name','Local real');}
 public function test_quote_uses_server_prices():void{$v=$this->venue();$this->postJson('/api/venues/'.$v->slug.'/quote',$this->input()+['total'=>1])->assertOk()->assertJsonPath('quote.total',650000)->assertJsonPath('quote.deposit',195000);}
 public function test_special_date_takes_priority():void{$i=$this->input();$v=$this->venue(null,['holidays'=>[$i['date']]]);$q=app(BookingEngine::class)->quote($v,$i);$this->assertSame(1050000,$q['total']);}
 public function test_extra_hours_use_owner_price():void{$v=$this->venue(null,['extra_hour_price'=>100000]);$i=$this->input();$i['hours']=10;$i['start']=12;$q=app(BookingEngine::class)->quote($v,$i);$this->assertSame(850000,$q['total']);}
 public function test_fixed_deposit_is_capped_at_total():void{$v=$this->venue(null,['deposit_type'=>'fixed','deposit_value'=>99999999]);$q=app(BookingEngine::class)->quote($v,$this->input());$this->assertSame($q['total'],$q['deposit']);}
 public function test_overlap_is_rejected_and_cancellation_releases_space():void{$v=$this->venue();$u=User::factory()->create();$this->actingAs($u);$a=$this->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertCreated()->json();$this->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertUnprocessable();$this->postJson('/api/bookings/'.$a['id'].'/cancel')->assertOk();$this->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertCreated();}
 public function test_expired_holds_do_not_block():void{$v=$this->venue();$u=User::factory()->create();$a=app(BookingEngine::class)->reserve($v,$u->id,$this->input());$a->update(['expires_at'=>now()->subMinute()]);$this->actingAs($u)->postJson('/api/venues/'.$v->slug.'/bookings',$this->input())->assertCreated();}
 public function test_other_customer_cannot_cancel_or_see_private_bookings():void{$v=$this->venue();$a=app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$this->input());$this->actingAs(User::factory()->create())->postJson('/api/bookings/'.$a->id.'/cancel')->assertForbidden();$this->getJson('/api/bookings')->assertJsonCount(0,'data');}
 public function test_capacity_and_cleanup_are_validated():void{$v=$this->venue();$i=$this->input();$i['guests']=101;$this->postJson('/api/venues/'.$v->slug.'/quote',$i)->assertUnprocessable();$i=$this->input();$i['start']=20;$this->postJson('/api/venues/'.$v->slug.'/quote',$i)->assertUnprocessable();}
 public function test_hourly_adjacent_reservations_are_allowed():void{$v=$this->venue(null,['mode'=>'hour','clean_minutes'=>0]);$u=User::factory()->create();$i=$this->input();$i['hours']=1;app(BookingEngine::class)->reserve($v,$u->id,$i);$i['start']=15;$b=app(BookingEngine::class)->reserve($v,$u->id,$i);$this->assertSame(650000,$b->total);}
 public function test_chat_rejects_off_topic_and_limits_guests():void{$v=$this->venue(null,['ai'=>['guest_messages'=>1]]);$id=(string)Str::uuid();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Resuelve una ecuación de física','conversation'=>$id])->assertOk()->assertJsonPath('mode','rules')->assertJsonPath('remaining',0);$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>$id])->assertTooManyRequests();}
 public function test_guest_cannot_bypass_conversation_limit():void{$v=$this->venue(null,['ai'=>['guest_conversations'=>1]]);$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertOk();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Horarios','conversation'=>(string)Str::uuid()])->assertTooManyRequests();}
 public function test_openai_adapter_and_rules_fallback():void{Http::fake(['api.openai.com/*'=>Http::response(['choices'=>[['message'=>['content'=>'El local tiene tarifas por día.']]],'usage'=>['total_tokens'=>50]])]);$v=$this->venue(null,['ai'=>['provider'=>'openai','endpoint'=>'https://api.openai.com/v1','model'=>'test-model','guest_tokens'=>10000]]);$v->ai_key='test-not-real';$v->save();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertOk()->assertJsonPath('mode','openai')->assertJsonStructure(['facts']);Http::assertSent(fn($r)=>$r->url()==='https://api.openai.com/v1/chat/completions');}
 public function test_unapproved_ai_hosts_are_not_called():void{Http::fake();$v=$this->venue(null,['ai'=>['provider'=>'compatible','endpoint'=>'https://unauthorized.invalid/v1','model'=>'test','guest_tokens'=>10000]]);$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertOk()->assertJsonPath('mode','rules_fallback');Http::assertNothingSent();}
 public function test_geocoder_returns_editable_coordinates():void{config(['encuentro.geocoding_key'=>'test-key']);Http::fake(['api.geoapify.com/*'=>Http::response(['results'=>[['formatted'=>'Colima','lat'=>19.24,'lon'=>-103.72]]])]);$this->actingAs($this->owner())->postJson('/api/owner/geocode',['address'=>'Colima, México'])->assertOk()->assertJsonPath('results.0.lat',19.24);}
 public function test_geocoding_failure_is_explicit():void{config(['encuentro.geocoding_key'=>null]);$this->actingAs($this->owner())->postJson('/api/owner/geocode',['address'=>'Colima, México'])->assertStatus(503);}
 public function test_availability_disables_reserved_days():void{$v=$this->venue();$i=$this->input();app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$i);$d=$this->getJson('/api/venues/'.$v->slug.'/availability?month='.substr($i['date'],0,7))->assertOk()->json('days');$day=collect($d)->firstWhere('date',$i['date']);$this->assertFalse($day['available']);}

 public function test_anthropic_adapter_uses_messages_protocol():void{Http::fake(['api.anthropic.com/*'=>Http::response(['content'=>[['type'=>'text','text'=>'Información del establecimiento.']],'usage'=>['input_tokens'=>20,'output_tokens'=>10]])]);$v=$this->venue(null,['ai'=>['provider'=>'anthropic','endpoint'=>'https://api.anthropic.com/v1','model'=>'test-model','guest_tokens'=>10000]]);$v->ai_key='test-not-real';$v->save();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Horarios','conversation'=>(string)Str::uuid()])->assertOk()->assertJsonPath('mode','anthropic');Http::assertSent(fn($r)=>$r->url()==='https://api.anthropic.com/v1/messages'&&$r->hasHeader('x-api-key'));}
 public function test_ollama_adapter_uses_native_protocol():void{config(['encuentro.ai_hosts'=>['ollama']]);Http::fake(['ollama:11434/*'=>Http::response(['message'=>['content'=>'Información del local.'],'prompt_eval_count'=>20,'eval_count'=>10])]);$v=$this->venue(null,['ai'=>['provider'=>'ollama','endpoint'=>'http://ollama:11434','model'=>'llama-test','guest_tokens'=>10000]]);$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Aforo','conversation'=>(string)Str::uuid()])->assertOk()->assertJsonPath('mode','ollama');Http::assertSent(fn($r)=>$r->url()==='http://ollama:11434/api/chat'&&$r['stream']===false);}
 public function test_api_failure_falls_back_to_venue_facts():void{Http::fake(['api.openai.com/*'=>Http::response([],503)]);$v=$this->venue(null,['ai'=>['provider'=>'openai','endpoint'=>'https://api.openai.com/v1','model'=>'test','guest_tokens'=>10000]]);$v->ai_key='test-not-real';$v->save();$this->postJson('/api/venues/'.$v->slug.'/chat',['message'=>'Precios','conversation'=>(string)Str::uuid()])->assertOk()->assertJsonPath('mode','rules_fallback');}
 public function test_next_day_event_does_not_overlap_previous_delivery():void{$v=$this->venue();$u=User::factory()->create();$i=$this->input();$i['start']=16;app(BookingEngine::class)->reserve($v,$u->id,$i);$i['date']=\Carbon\CarbonImmutable::parse($i['date'])->addDay()->format('Y-m-d');$i['start']=10;$this->assertNotNull(app(BookingEngine::class)->reserve($v,$u->id,$i)->id);}
 public function test_closed_weekdays_reject_quotes():void{$i=$this->input();$weekday=\Carbon\CarbonImmutable::parse($i['date'])->dayOfWeek;$v=$this->venue(null,['closed_weekdays'=>[$weekday]]);$this->postJson('/api/venues/'.$v->slug.'/quote',$i)->assertUnprocessable();}
 public function test_changed_prices_require_new_quote():void{$v=$this->venue();$i=$this->input();$q=app(BookingEngine::class)->quote($v,$i);$settings=$v->settings;$settings['weekday_price']=700000;$v->settings=$settings;$v->save();$this->actingAs(User::factory()->create())->postJson('/api/venues/'.$v->slug.'/bookings',$i+['expected_total'=>$q['total'],'expected_version'=>$q['settings_version']])->assertUnprocessable();}

 public function test_new_venue_defaults_leave_business_numbers_empty():void{$u=User::factory()->create();$d=$this->actingAs($this->owner($u))->getJson('/api/owner/defaults')->assertOk()->json();foreach(['capacity','weekday_price','weekend_price','holiday_price','deposit_value','extra_hour_price','included_hours','open_hour'] as $field)$this->assertNull($d[$field]);}
 public function test_incomplete_venue_can_be_saved_as_private_draft():void{$this->actingAs($this->owner())->postJson('/api/owner/venues',['name'=>'Mi local','slug'=>'mi-local-borrador','published'=>false,'settings'=>VenueSettings::defaults()])->assertCreated()->assertJsonPath('settings.weekday_price',null);$this->getJson('/api/venues/mi-local-borrador')->assertNotFound();}
 public function test_incomplete_venue_cannot_be_published():void{$this->actingAs($this->owner())->postJson('/api/owner/venues',['name'=>'Mi local','slug'=>'mi-local-sin-datos','published'=>true,'settings'=>VenueSettings::defaults()])->assertUnprocessable()->assertJsonValidationErrors(['settings.lat','settings.capacity','settings.weekday_price']);}
 public function test_owner_can_upload_photo_and_choose_cover():void{\Illuminate\Support\Facades\Storage::fake('local');$v=$this->venue();$this->actingAs($v->owner);$photo=$this->post('/api/owner/venues/'.$v->slug.'/photos',['photo'=>\Illuminate\Http\UploadedFile::fake()->image('jardin.jpg'),'caption'=>'Jardín real'],['Accept'=>'application/json'])->assertCreated()->json();$this->assertArrayNotHasKey('path',$photo);$this->get('/api/media/photos/'.$photo['id'])->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonCount(1,'photos');$this->patchJson('/api/owner/venues/'.$v->slug.'/photos/'.$photo['id'],['visible'=>false])->assertOk();$this->actingAs(User::factory()->create())->get('/api/media/photos/'.$photo['id'])->assertNotFound();$this->getJson('/api/venues/'.$v->slug)->assertJsonCount(0,'photos');}
 public function test_photo_upload_rejects_non_images_and_other_owners():void{$v=$this->venue();$this->actingAs($v->owner)->post('/api/owner/venues/'.$v->slug.'/photos',['photo'=>\Illuminate\Http\UploadedFile::fake()->create('bad.svg',1,'image/svg+xml')],['Accept'=>'application/json'])->assertUnprocessable();$this->actingAs(User::factory()->create())->postJson('/api/owner/venues/'.$v->slug.'/photos',[])->assertForbidden();}
 public function test_manual_comments_are_drafts_and_not_verified_reviews():void{$v=$this->venue();$r=$this->actingAs($v->owner)->postJson('/api/owner/venues/'.$v->slug.'/reviews',['author'=>'Autor real','body'=>'Comentario real','source_url'=>'https://instagram.com/p/ejemplo/'])->assertCreated()->assertJsonPath('visible',false)->assertJsonPath('source','owner')->json();$this->getJson('/api/venues/'.$v->slug)->assertJsonCount(0,'reviews');$this->patchJson('/api/owner/venues/'.$v->slug.'/reviews/'.$r['id'],['visible'=>true])->assertOk();$this->getJson('/api/venues/'.$v->slug)->assertJsonCount(1,'reviews');}
 public function test_social_tokens_are_encrypted_and_never_returned():void{$v=$this->venue();$this->actingAs($v->owner)->postJson('/api/owner/venues/'.$v->slug.'/instagram',['account_id'=>'123456789','token'=>'test-private-token-123'])->assertOk()->assertJsonMissingPath('token');$c=\App\Models\VenueSocialConnection::first();$this->assertNotEquals('test-private-token-123',$c->getRawOriginal('token'));$this->getJson('/api/owner/venues/'.$v->slug.'/instagram')->assertOk()->assertJsonMissingPath('token');$this->actingAs(User::factory()->create())->getJson('/api/owner/venues/'.$v->slug.'/instagram')->assertForbidden();}
 public function test_instagram_import_uses_official_endpoint_and_saves_drafts():void{$v=$this->venue();$this->actingAs($v->owner);\App\Models\VenueSocialConnection::create(['venue_id'=>$v->id,'provider'=>'instagram','account_id'=>'123456789','token'=>'test-private-token']);Http::fake(['graph.instagram.com/*/123456789/media*'=>Http::response(['data'=>[['id'=>'111111','media_type'=>'IMAGE','media_url'=>'https://scontent.cdninstagram.com/real.jpg','permalink'=>'https://instagram.com/p/real/','caption'=>'Foto real del local','username'=>'mi_local']]]),'graph.instagram.com/*/111111/comments*'=>Http::response(['data'=>[['id'=>'222222','username'=>'autor','text'=>'Comentario real']]])]);$this->getJson('/api/owner/venues/'.$v->slug.'/instagram/preview?comments=1')->assertOk()->assertJsonPath('items.0.id','111111');$this->postJson('/api/owner/venues/'.$v->slug.'/instagram/import',['photos'=>['111111'],'comments'=>['222222']])->assertOk()->assertJsonPath('photos',1)->assertJsonPath('comments',1);$this->assertFalse($v->photos()->first()->visible);$this->assertFalse($v->reviews()->first()->visible);$this->getJson('/api/venues/'.$v->slug)->assertJsonCount(0,'photos')->assertJsonCount(0,'reviews');}
 public function test_social_import_cannot_inject_arbitrary_remote_urls():void{$v=$this->venue();$this->actingAs($v->owner);\App\Models\VenueSocialConnection::create(['venue_id'=>$v->id,'provider'=>'instagram','account_id'=>'123456789','token'=>'test-private-token']);Http::fake(['graph.instagram.com/*'=>Http::response(['data'=>[['id'=>'111','media_type'=>'IMAGE','media_url'=>'http://169.254.169.254/private']]])]);$this->postJson('/api/owner/venues/'.$v->slug.'/instagram/import',['photos'=>['111'],'comments'=>[],'url'=>'http://127.0.0.1'])->assertOk()->assertJsonPath('photos',0);}
 public function test_payment_ledger_shows_actual_received_amount_and_balance():void{$v=$this->venue();$b=app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$this->input());$this->assertSame(0,$b->paid_total);$this->assertSame($b->total,$b->balance_due);$this->actingAs($v->owner);$data=['amount'=>$b->deposit,'method'=>'cash','idempotency_key'=>(string)Str::uuid()];$this->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',$data)->assertOk()->assertJsonPath('paid_total',$b->deposit)->assertJsonPath('balance_due',$b->total-$b->deposit)->assertJsonPath('status','confirmed');$this->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',$data)->assertOk();$this->assertSame(1,$b->payments()->count());$this->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',['amount'=>$b->total-$b->deposit,'method'=>'transfer','idempotency_key'=>(string)Str::uuid()])->assertOk()->assertJsonPath('balance_due',0)->assertJsonPath('payment_status','paid');}
 public function test_other_owner_cannot_register_a_payment():void{$v=$this->venue();$b=app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$this->input());$this->actingAs(User::factory()->create())->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',['amount'=>$b->deposit,'method'=>'cash','idempotency_key'=>(string)Str::uuid()])->assertForbidden();}
 public function test_first_payment_and_overpayment_are_validated():void{$v=$this->venue();$b=app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$this->input());$this->actingAs($v->owner);foreach([1,$b->total+1] as $amount)$this->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$b->id.'/payments',['amount'=>$amount,'method'=>'cash','idempotency_key'=>(string)Str::uuid()])->assertUnprocessable();$this->assertSame(0,$b->payments()->count());}
 public function test_expired_hold_payment_rejects_new_conflict():void{$v=$this->venue();$u=User::factory()->create();$old=app(BookingEngine::class)->reserve($v,$u->id,$this->input());$old->update(['expires_at'=>now()->subMinute()]);app(BookingEngine::class)->reserve($v,User::factory()->create()->id,$this->input());$this->actingAs($v->owner)->postJson('/api/owner/venues/'.$v->slug.'/bookings/'.$old->id.'/payments',['amount'=>$old->deposit,'method'=>'cash','idempotency_key'=>(string)Str::uuid()])->assertUnprocessable();$this->assertSame(0,$old->payments()->count());}

 public function test_client_cannot_cancel_a_hold_with_recorded_money():void {
 $v=$this->venue();$u=User::factory()->create();$b=app(BookingEngine::class)->reserve($v,$u->id,$this->input());
 \App\Models\BookingPayment::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'recorded_by'=>$v->owner_id,'recorded_by_owner_id'=>$v->owner_account_id,'amount'=>100,'method'=>'cash','idempotency_key'=>(string)Str::uuid()]);
 $this->actingAs($u)->postJson('/api/bookings/'.$b->id.'/cancel')->assertUnprocessable();
 $this->assertSame('hold',$b->fresh()->status);$this->assertSame(100,$b->fresh()->paid_total);
 }
}
